import { type LessonImage, sha256 } from "./schema";
export const jpegBase64 =
	"";
export async function imageFixture(): Promise<LessonImage> {
	return {
		id: crypto.randomUUID(),
		mime: "image/jpeg",
		base64: jpegBase64,
		sha256: await sha256(Uint8Array.from(atob(jpegBase64), (c) => c.charCodeAt(0))),
		width: 2,
		height: 2,
		source: {
			projectId: "p",
			rulerSec: 1,
			basis: "editor-ruler-seconds",
			precision: "60fps-floor",
			documentSha256: "f".repeat(64),
		},
	};
}
